package com.fasterxml.jackson.databind.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.math.*;
import java.text.DateFormat;
import java.text.FieldPosition;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.Locale;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StdDateFormat.parseAsISO8601.
 * Since the method is protected, we use a subclass to expose it for testing.
 */
public class StdDateFormat_parseAsISO8601_TriageGen1Test {

    private TestableStdDateFormat dateFormat;

    // Subclass to expose protected method
    private static class TestableStdDateFormat extends StdDateFormat {
        public TestableStdDateFormat() {
            super();
        }

        public TestableStdDateFormat(TimeZone tz, Locale loc, boolean lenient) {
            super(tz, loc);
            setLenient(lenient);
        }

        @Override
        public Date parseAsISO8601(String dateStr, ParsePosition pos, boolean throwErrors) throws ParseException {
            return super.parseAsISO8601(dateStr, pos, throwErrors);
        }
    }

    @Before
    public void setUp() {
        dateFormat = new TestableStdDateFormat();
    }

    @Test
    public void testParsePlainDate() throws ParseException {
        // len <= 10 and last char is digit
        Date result = dateFormat.parseAsISO8601("2023-10-27", new ParsePosition(0), false);
        Calendar cal = Calendar.getInstance();
        cal.setTime(result);
        assertEquals(2023, cal.get(Calendar.YEAR));
        assertEquals(Calendar.OCTOBER, cal.get(Calendar.MONTH));
        assertEquals(27, cal.get(Calendar.DAY_OF_MONTH));
    }

    @Test
    public void testParseZuluWithColon() throws ParseException {
        // c == 'Z' and dateStr.charAt(len-4) == ':' -> adds .000
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00Z", new ParsePosition(0), false);
        assertNotNull(result);
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test
    public void testParseZuluNoColon() throws ParseException {
        // c == 'Z' and dateStr.charAt(len-4) != ':'
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00Z", new ParsePosition(0), false);
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetColon() throws ParseException {
        // hasTimeZone(dateStr) is true, and c == ':' (removes colon)
        // Input: 2023-10-27T10:00:00+05:00 -> removes colon -> 2023-10-27T10:00:00+0500
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00+05:00", new ParsePosition(0), false);
        assertNotNull(result);
    }

    @Test
    public void testParseWithTimeZoneOffsetNoColon() throws ParseException {
        // hasTimeZone(dateStr) is true, and c == '+' or '-' (appends 00)
        // Input: 2023-10-27T10:00:00+05 -> appends 00 -> 2023-10-27T10:00:00+0500
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00+05", new ParsePosition(0), false);
        assertNotNull(result);
    }

    @Test
    public void testParseTimeZoneWithMissingSecondsOrMillis() throws ParseException {
        // Triggers the switch(timeLen) logic for various cases
        // Case 11: append '0'
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:00.1+0500", new ParsePosition(0), false));
        // Case 10: append '0'
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:00.11+0500", new ParsePosition(0), false));
        // Case 9: append '000'
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:00.111+0500", new ParsePosition(0), false)); // wait, check logic

        // Testing specific logic branches in the switch:
        // If timeLen is 8: inserts ".000"
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:00+0500", new ParsePosition(0), false));
        // If timeLen is 5: inserts ":00.000"
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00+0500", new ParsePosition(0), false));
    }

    @Test
    public void testParseNoTimeZoneImplicitZulu() throws ParseException {
        // hasTimeZone is false, appends 'Z'
        Date result = dateFormat.parseAsISO8601("2023-10-27T10:00:00", new ParsePosition(0), false);
        assertNotNull(result);
        // Verify it's treated as UTC via the logic
        Calendar cal = Calendar.getInstance(TimeZone.getTimeZone("UTC"));
        cal.setTime(result);
        assertEquals(10, cal.get(Calendar.HOUR_OF_DAY));
    }

    @Test(expected = ParseException.class)
    public void testParseInvalidDateThrowsException() throws ParseException {
        // Non-lenient mode to ensure exception is thrown when dt is null
        dateFormat = new TestableStdDateFormat(TimeZone.getTimeZone("UTC"), Locale.US, false);
        dateFormat.parseAsISO8601("not-a-date", new ParsePosition(0), false);
    }

    @Test
    public void testParseWithLenientTrue() throws ParseException {
        // Should not throw exception even if date is slightly off-format
        dateFormat = new TestableStdDateFormat(TimeZone.getTimeZone("UTC"), Locale.US, true);
        Date result = dateFormat.parseAsISO8601("2023-13-45T10:00:00Z", new ParsePosition(0), false);
        assertNotNull(result);
    }

    @Test
    public void testParseTimeLen7Branch() throws ParseException {
        // Case 7: does nothing to sb
        // To reach case 7, len - lastIndexOf('T') - 6 must be 7
        // len = 23. lastIndexOf('T') = 10. 23 - 10 - 6 = 7.
        // String: "2023-10-27T10:00:0+0500" (T is at 10. len is 23. 23-10-6=7)
        // Note: The logic for case 7 is "break", so it just proceeds with the original string.
        // We check if it doesn't crash.
        assertNotNull(dateFormat.parseAsISO8601("2023-10-27T10:00:0+0500", new ParsePosition(0), false));
    }
}
